-- Guest Hub S3 (26 Nov 2026 — Ahmed's decisions S8–S10, DECISIONS.md 2026-11-26 «Guest Hub S3»): the social team takes every
-- social hand-off (S8, never reception — it replaces both branches of S2a for them); reception never sees a social
-- conversation or comment (A2); a social chat booking request goes to the chosen branch's reception (S9); in «حسابات التجربة
-- فقط» a real account is recorded only (S10). Generated by scripts/hub-s3-migration.mjs — never edited once applied
-- (CLAUDE.md §12). No unit mode, licence, audience or switch changes. No phone number in this file. Every UPDATE / DELETE has
-- a WHERE.

-- ── 1. the social team (S8): dashboard users; today the system admin ──
create table if not exists public.hub_social_team (
  staff_id uuid primary key references auth.users (id) on delete cascade,
  position smallint not null default 1 check (position between 1 and 20),
  added_by uuid references auth.users (id) on delete set null,
  added_at timestamptz not null default now()
);
comment on table public.hub_social_team is 'S8 (Ahmed, 26 Nov 2026): who gets the hand-offs of «السوشيال» — a WhatsApp alert to the member''s number of «التقارير» and the emails to their sign-in address. Never a reception login. Set by the system admin in «إعدادات المساعد» → «السوشيال» → «فريق السوشيال».';
alter table public.hub_social_team enable row level security;
revoke all on table public.hub_social_team from public, anon, authenticated;
grant all on table public.hub_social_team to service_role;
insert into public.hub_social_team (staff_id, position)
select s.user_id, 1 from public.staff s where s.role = 'admin' and s.active
on conflict do nothing;

-- a hand-off of «السوشيال» (a conversation's, a comment's, or an extra alert that is not a booking request): the social team's
alter table public.hub_handoffs add column if not exists social boolean not null default false;
comment on column public.hub_handoffs.social is 'S8 (Ahmed, 26 Nov 2026): this hand-off goes to the social team (hub_social_team), never a reception slot.';
-- the open social hand-offs of before (both branches, S2a) become the social team's
update public.hub_handoffs h set social = true, both_branches = false
 where h.closed_at is null and not h.social
   and h.unit_id in (select u.id from public.hub_units u where u.kind = 'brand')
   and not (h.extra and h.reason in ('booking_request', 'booking_request_late', 'booking_request_again'));

-- a reception login (a single branch, the role reception)
create or replace function internal.hub_is_reception() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.staff s where s.user_id = auth.uid() and s.role = 'reception')
$$;
-- the active members of the social team (an active staff member, never a reception login)
create or replace function internal.hub_social_team_ids() returns uuid[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(t.staff_id order by t.position, t.added_at), '{}') from public.hub_social_team t
    join public.staff s on s.user_id = t.staff_id where s.active and s.role <> 'reception'
$$;
create or replace function internal.hub_social_team_ready() returns boolean
language sql stable security definer set search_path = '' as $$
  select cardinality(internal.hub_social_team_ids()) > 0
$$;
-- the team's sign-in addresses; none → the active admins (an email never goes to nobody, never to reception)
create or replace function internal.hub_social_team_emails() returns text[]
language sql stable security definer set search_path = '' as $$
  select case when cardinality(x.a) > 0 then x.a else
    (select coalesce(array_agg(u.email order by u.email), '{}') from public.staff s join auth.users u on u.id = s.user_id
      where s.active and s.role = 'admin' and u.email is not null) end
    from (select coalesce(array_agg(u.email order by u.email), '{}') a from auth.users u where u.id = any (internal.hub_social_team_ids()) and u.email is not null) x
$$;
-- the WhatsApp alert of a social hand-off: one send to each member's active number of «التقارير», from the branch number
-- given (the conversation's branch, else Airport Road's — the number only carries the alert); a member without a number → none
create or replace function internal.hub_social_alert(p_handoff uuid, p_channel uuid) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff;
  if h.id is null or p_channel is null then return 0; end if;
  insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
  select 'alert', h.id, r.id, p_channel, 'hub_staff_alert', h.is_test
    from public.hub_report_recipients r
   where r.active and r.staff_user_id = any (internal.hub_social_team_ids())
     and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.recipient_id = r.id);
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;
revoke execute on function internal.hub_is_reception(), internal.hub_social_team_ids(), internal.hub_social_team_ready(),
  internal.hub_social_team_emails(), internal.hub_social_alert(uuid, uuid) from public, anon;
grant execute on function internal.hub_is_reception() to authenticated;

-- «إعدادات المساعد» → «السوشيال» → «فريق السوشيال»: who is in it and who may be added (assistant: view, every branch)
create or replace function public.hub_social_team_get() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_unit uuid := (select u.id from public.hub_units u where u.key = 'social');
begin
  if not (internal.can('assistant', 'view') and internal.can_branch(null)) then raise exception 'hub_forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'members', (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'name', s.full_name,
                        'has_number', exists (select 1 from public.hub_report_recipients r where r.staff_user_id = s.user_id and r.active))
                        order by t.position, t.added_at), '[]'::jsonb)
                  from public.hub_social_team t join public.staff s on s.user_id = t.staff_id where s.active and s.role <> 'reception'),
    -- an active staff member of «السوشيال» who is not a reception login
    'candidates', (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'name', s.full_name,
                        'has_number', exists (select 1 from public.hub_report_recipients r where r.staff_user_id = s.user_id and r.active))
                        order by s.full_name), '[]'::jsonb)
                     from public.staff s join public.hub_unit_members m on m.staff_id = s.user_id and m.unit_id = v_unit
                    where s.active and s.role <> 'reception'),
    'system_admin', internal.is_system_admin());
end;
$$;
-- the whole list (the system admin; audited, «تراجع» = the list before); at least one; each a member of «السوشيال», active,
-- never a reception login
create or replace function public.hub_social_team_set(p_staff uuid[]) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_unit uuid := (select u.id from public.hub_units u where u.key = 'social');
  v_before uuid[] := (select coalesce(array_agg(t.staff_id order by t.position, t.added_at), '{}') from public.hub_social_team t);
  v_list uuid[] := array(select distinct x from unnest(coalesce(p_staff, '{}')) x where x is not null);
  v_batch uuid;
  v_id uuid;
  i integer := 0;
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  if cardinality(v_list) = 0 then raise exception 'hub_social_team_empty' using errcode = '22023'; end if;
  if cardinality(v_list) > 20 then raise exception 'invalid' using errcode = '22023'; end if;
  if exists (select 1 from unnest(v_list) x where not exists (
        select 1 from public.staff s join public.hub_unit_members m on m.staff_id = s.user_id and m.unit_id = v_unit
         where s.user_id = x and s.active and s.role <> 'reception')) then
    raise exception 'hub_social_team_member' using errcode = '22023';
  end if;
  if v_list = v_before then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  delete from public.hub_social_team where staff_id <> all (v_list);
  foreach v_id in array (select array(select x from unnest(p_staff) with ordinality as a(x, o) where x = any (v_list) order by o)) loop
    i := i + 1;
    insert into public.hub_social_team (staff_id, position, added_by) values (v_id, least(i, 20), auth.uid())
    on conflict (staff_id) do update set position = excluded.position;
  end loop;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), coalesce((select st.full_name from public.staff st where st.user_id = auth.uid()), 'system'), 'hub_social_team', 'social', null, 'update',
          jsonb_build_object('members', to_jsonb(v_before)), jsonb_build_object('members', to_jsonb(v_list)), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', to_jsonb(v_before));
end;
$$;
revoke execute on function public.hub_social_team_get(), public.hub_social_team_set(uuid[]) from public, anon;
grant execute on function public.hub_social_team_get(), public.hub_social_team_set(uuid[]) to authenticated, service_role;

-- ── 2. A2: a social conversation is seen by the members of «السوشيال» only — never a reception login ──
create or replace function internal.can_conv(c public.hub_conversations, p_level public.perm_level) returns boolean
language sql stable security definer set search_path = '' as $$
  select internal.can_unit(c.unit_id, p_level)
     and not (internal.hub_is_reception() and exists (select 1 from public.hub_units b where b.id = c.unit_id and b.kind = 'brand'))
$$;
-- comments (public text, both Meta channels): a member of «السوشيال» with every branch in scope, never a reception login
create or replace function internal.hub_can_comments(p_level public.perm_level) returns boolean
language sql stable security definer set search_path = '' as $$
  select internal.can('inbox', p_level) and internal.can_branch(null) and not internal.hub_is_reception()
     and exists (select 1 from public.hub_unit_members m join public.hub_units u on u.id = m.unit_id
                  where m.staff_id = auth.uid() and u.status = 'active' and u.kind = 'brand')
$$;

create or replace function public.hub_now(p_branch text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_br text[] := internal.metrics_branches('now', p_branch);
  v_today date := internal.riyadh_today();
  v_from timestamptz := (internal.riyadh_today()::timestamp at time zone 'Asia/Riyadh');
  v_month timestamptz := (date_trunc('month', internal.riyadh_today())::timestamp at time zone 'Asia/Riyadh');
  v_out jsonb;
begin
  with units as (
    select u.id, u.key, u.kind, u.branch_slug, u.name_ar, u.sort from public.hub_units u
     where u.branch_slug = any (v_br) and u.status <> 'hidden' and not u.is_test),
  conv as (
    select c.unit_id, c.state, c.waiting_since, c.tags from public.hub_conversations c
     where not c.is_test and c.state <> 'closed' and c.unit_id in (select id from units))
  select jsonb_build_object(
    'at', now(), 'today', v_today,
    'units', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', un.key, 'name_ar', un.name_ar, 'branch', un.branch_slug,
        'assistant', (select count(*) from conv x where x.unit_id = un.id and x.state <> 'human'),
        'collecting', (select count(*) from conv x where x.unit_id = un.id and x.state in ('collecting', 'quoted', 'awaiting_confirmation')),
        'waiting', (select count(*) from conv x where x.unit_id = un.id and x.state = 'human' and x.waiting_since is not null),
        'with_staff', (select count(*) from conv x where x.unit_id = un.id and x.state = 'human' and x.waiting_since is null),
        'longest_wait_min', (select floor(extract(epoch from now() - min(x.waiting_since)) / 60)::int from conv x where x.unit_id = un.id and x.state = 'human' and x.waiting_since is not null),
        'orders_waiting', (select count(*) from conv x where x.unit_id = un.id and 'order' = any (x.tags) and x.waiting_since is not null))
        order by un.sort, un.key), '[]'::jsonb) from units un),
    -- the assistant's own replies today: live reply turns that answered (never the message table — no text is ever read here)
    'replies_today', (select count(*) from public.hub_turns t
                       where t.kind = 'reply' and t.status = 'done' and t.mode = 'live' and not t.is_test and t.finished_at >= v_from and t.unit_id in (select id from units)
                         and exists (select 1 from jsonb_array_elements_text(coalesce(t.decision -> 'actions', '[]'::jsonb)) a where a not in ('noop', 'tag', 'handoff'))),
    -- S3 (A2): the hand-offs of this screen's own units — never a social one (its Airport Road placeholder)
    'handoffs_today', (select count(*) from public.hub_handoffs h where not h.is_test and not h.extra and h.created_at >= v_from and h.unit_id in (select id from units)),
    'bookings_today', (select jsonb_build_object(
        'site', count(*) filter (where r.booking_source = 'website'),
        'assistant', count(*) filter (where r.booking_source = 'assistant_whatsapp'),
        'staff', count(*) filter (where r.booking_source not in ('website', 'assistant_whatsapp')),
        'assistant_instant', count(*) filter (where r.booking_source = 'assistant_whatsapp' and r.confirmation = 'instant'),
        'assistant_request', count(*) filter (where r.booking_source = 'assistant_whatsapp' and r.confirmation is distinct from 'instant'))
       from public.reservations r where not r.is_test and r.created_at >= v_from and r.branch = any (v_br)),
    'revenue', jsonb_build_object(
        'today', (select coalesce(sum(internal.res_revenue(r.id)), 0) from public.reservations r
                   where not r.is_test and r.status = 'confirmed' and r.booking_source = 'assistant_whatsapp' and r.created_at >= v_from and r.branch = any (v_br)),
        'month', (select coalesce(sum(internal.res_revenue(r.id)), 0) from public.reservations r
                   where not r.is_test and r.status = 'confirmed' and r.booking_source = 'assistant_whatsapp' and r.created_at >= v_month and r.branch = any (v_br))),
    'feed', (select coalesce(jsonb_agg(jsonb_build_object('kind', s.kind, 'unit', (select un.name_ar from units un where un.id = s.unit_id),
                                                          'branch', s.branch, 'at', s.at) order by s.at desc), '[]'::jsonb)
               from (select * from public.dashboard_signals s
                      where s.at > now() - interval '24 hours' and s.branch = any (v_br)
                        and s.kind in ('hub_message', 'hub_handoff', 'hub_booking', 'hub_order', 'booking')
                      order by s.at desc limit 40) s))
  into v_out;
  return internal.money(v_out);
end;
$$;

-- ── 3. S10: «حسابات التجربة فقط» — a real account's messages are recorded only (no hand-off, no alert, no waiting email) ──
create or replace function internal.hub_alertable(p_reason text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(p_reason, '') not in ('assistant_off', 'unit_off', 'budget_cap', 'budget_unset', 'api_credit', 'test_mode', 'take_over', 'phone_reply', 'cart_order',
                                         'social_record_only')
$$;
create or replace function internal.hub_conversation_before() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.waiting_since is not null and (tg_op = 'INSERT' or old.waiting_since is null)
     and exists (select 1 from public.guest_profiles g where g.id = new.guest_profile_id and g.hub_blocked_at is not null) then
    new.waiting_since := null;
  end if;
  -- S10 (Ahmed, 26 Nov 2026): a real account on a channel in «حسابات التجربة فقط» never waits (no waiting email, no badge)
  if new.waiting_since is not null and not internal.hub_social_may_reply(new) then
    new.waiting_since := null;
  end if;
  if tg_op = 'UPDATE' and new.waiting_since is distinct from old.waiting_since then new.escalated_at := null; end if;
  return new;
end;
$$;
-- the conversations already waiting that way stop waiting
update public.hub_conversations c set waiting_since = null
 where c.waiting_since is not null and c.state <> 'closed'
   and c.unit_id in (select u.id from public.hub_units u where u.kind = 'brand')
   and not internal.hub_social_may_reply(c);

create or replace function public.hub_turn_queue(p_conversation uuid, p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  g public.guest_profiles;
  st jsonb;
  v_turn uuid;
  v_due timestamptz;
  v_kind text;
  -- at most 3 seconds (Ahmed, 15 Nov 2026 — the wait was the largest part of a reply's time)
  v_burst integer := least(greatest(internal.hub_setting_int('hub_burst_ms', 2000), 0), 3000);
  v_test_mode boolean;
  -- «وضع الاستعداد» (16 Nov 2026)
  v_wait integer;
  v_tap boolean;
  v_until timestamptz;
  v_woke boolean;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or c.state = 'closed' then return jsonb_build_object('queued', false, 'reason', 'closed'); end if;
  if not exists (select 1 from public.hub_messages m where m.id = p_message and m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest') then
    return jsonb_build_object('queued', false, 'reason', 'not_guest');
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then return jsonb_build_object('queued', false, 'reason', 'blocked'); end if;
  -- S10 (Ahmed, 26 Nov 2026): a conversation recorded only while its channel was «حسابات التجربة فقط» returns to the assistant
  -- once the audience lets it reply (the audience «الكل», or the account marked «حساب تجربة»)
  if c.state = 'human' and c.human_reason in ('social_record_only', 'social_not_tester') and c.owner_kind is null and internal.hub_social_may_reply(c) then
    insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
    values (c.id, 'state', 'human', coalesce(c.state_before_human, 'new'), 'social_audience', c.is_test);
    update public.hub_conversations set state = coalesce(state_before_human, 'new'), state_changed_at = now(), human_reason = null
     where id = c.id returning * into c;
  end if;
  -- S10: «حسابات التجربة فقط» — an account not marked «حساب تجربة» is recorded only: with the team (social_record_only), no
  -- hand-off, no alert, no waiting email, no reply and no notice; the social team answers from Meta Business Suite
  if not internal.hub_social_may_reply(c) then
    if c.state = 'human' then
      -- already with the team because the unit is off (or its budget): marked recorded only — nobody waits
      update public.hub_conversations set human_reason = 'social_record_only', waiting_since = null
       where id = c.id and owner_kind is null and coalesce(human_reason, '') in ('assistant_off', 'unit_off', 'budget_cap', 'budget_unset', 'api_credit', 'social_not_tester');
    else
      perform internal.hub_to_team(c, 'social_record_only');
    end if;
    return jsonb_build_object('queued', false, 'reason', 'record_only');
  end if;
  st := internal.hub_assistant_state(u);
  if not (st ->> 'active')::boolean then
    perform internal.hub_to_team(c, case when st ->> 'reason' = 'unit_off' then 'assistant_off' else st ->> 'reason' end);
    return jsonb_build_object('queued', false, 'reason', st ->> 'reason');
  end if;
  v_test_mode := st ->> 'mode' = 'test';
  -- the try while the API credit is exhausted (at most every 30 minutes): reserved here
  if (st ->> 'credit_try')::boolean then
    update public.hub_alerts set payload = payload || jsonb_build_object('last_try_at', now()) where kind = 'api_credit' and acknowledged_at is null and not is_test;
  end if;
  if v_test_mode then
    -- a conversation that existed before «تجربة»: its run starts now
    if c.test_state is null then
      update public.hub_conversations set test_state = 'new' where id = c.id;
      c.test_state := 'new';
    end if;
    -- H6c: «بانتظار موظف» (a hand-off with no staff reply yet) is answered by the assistant in a test run as well
    v_kind := case when c.test_state = 'closed' then 'tag' else 'reply' end;
  else
    -- H6c: «بانتظار موظف» → the assistant keeps answering what it can; «مع موظف» → silent (tagging) until the branch's
    -- «عودة المساعد» minutes of staff silence, then the guest's message resumes it
    -- H10: a tap on the alternatives offer («اعرض البدائل» / «لا، شكرًا») is answered whoever holds the conversation
    v_kind := case when c.state = 'human' and internal.hub_human_phase(c, u) is null
                    and not exists (select 1 from public.hub_messages m where m.id = p_message and coalesce(m.payload ->> 'button_id', '') like 'hubx:%')
                   then 'tag' else 'reply' end;
  end if;
  v_tap := exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id'));
  v_woke := v_tap and exists (select 1 from public.hub_turns x where x.conversation_id = c.id and x.status = 'pending' and x.standby_until > now() and x.standby_outcome is null);
  -- a pending turn of this conversation takes the message (the burst; a wait of «وضع الاستعداد» takes every message until it
  -- ends — one reply to all of them); a tap on our own button ends the wait at once
  update public.hub_turns set inbound_message_ids = case when p_message = any (inbound_message_ids) then inbound_message_ids else inbound_message_ids || p_message end,
         due_at = case when v_tap and standby_until > now() and standby_outcome is null then least(due_at, now() + make_interval(secs => v_burst / 1000.0)) else due_at end,
         standby_until = case when v_tap and standby_until > now() and standby_outcome is null then now() else standby_until end
   where conversation_id = c.id and status = 'pending'
  returning id, due_at, standby_until into v_turn, v_due, v_until;
  if v_turn is not null then
    return jsonb_build_object('queued', true, 'joined', true, 'turn_id', v_turn, 'due_at', v_due, 'standby_until', case when v_until > now() then v_until end, 'woke', v_woke);
  end if;
  -- «وضع الاستعداد»: the minutes to wait for a staff reply first (NULL = none — today's burst)
  v_wait := internal.hub_standby_minutes(c.id, p_message, v_kind);
  insert into public.hub_turns (conversation_id, unit_id, inbound_message_ids, first_inbound_id, kind, due_at, is_test, standby_until, standby_reason)
  values (c.id, c.unit_id, array[p_message], p_message, v_kind,
          case when v_wait is not null then now() + make_interval(mins => v_wait) else now() + make_interval(secs => v_burst / 1000.0) end, c.is_test,
          case when v_wait is not null then now() + make_interval(mins => v_wait) end,
          -- H9 fix 3: why it waited or not (shown in «المحادثات» and «المحاكي»)
          internal.hub_standby_reason(c.id, p_message, v_kind))
  on conflict do nothing
  returning id, due_at into v_turn, v_due;
  if v_turn is null then
    select t.id, t.due_at into v_turn, v_due from public.hub_turns t where t.first_inbound_id = p_message;
    return jsonb_build_object('queued', false, 'reason', 'duplicate', 'turn_id', v_turn);
  end if;
  return jsonb_build_object('queued', true, 'turn_id', v_turn, 'due_at', v_due, 'kind', v_kind, 'standby_until', case when v_wait is not null then v_due end);
end;
$$;

-- ── 4. S8 / S9: the social team takes the social hand-offs; a social booking request goes to the chosen branch ──

create or replace function internal.hub_conv_team_after() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    update public.hub_handoffs set closed_at = coalesce(closed_at, now()) where id = old.handoff_id;
  end if;
  if new.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, is_test, both_branches, social)
    -- S8 (Ahmed, 26 Nov 2026): a hand-off of «السوشيال» is the social team's (branch_slug only picks the number the alert comes
    -- from); a test account's still to the system admin only (S1c)
    select new.handoff_id, new.id, new.unit_id, coalesce(u.branch_slug, new.branch_slug, 'airport-road'), new.human_reason, new.is_test,
           false, u.kind = 'brand'
      from public.hub_units u where u.id = new.unit_id
    on conflict do nothing;
    perform internal.hub_handoff_queue(new.handoff_id, 'alert');
  elsif new.handoff_id is not null and new.last_staff_at is not null and new.last_staff_at is distinct from old.last_staff_at then
    update public.hub_handoffs set first_reply_at = coalesce(first_reply_at, new.last_staff_at) where id = new.handoff_id;
  end if;
  return null;
end;
$$;

create or replace function internal.hub_handoff_queue(p_handoff uuid, p_kind text, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff for update;
  if h.id is null or h.closed_at is not null then return 0; end if;
  v_channel := internal.hub_branch_channel(h.branch_slug);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin — never a reception slot
  -- S2: a comment of a test account too (its complaint's hand-off has no conversation)
  if internal.hub_tester_conversation(h.conversation_id) or internal.hub_tester_comment(h.comment_id) then
    if p_kind = 'alert' and v_channel is not null and internal.hub_system_admin_recipient() is not null
       and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.recipient_id = internal.hub_system_admin_recipient()) then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', h.id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', h.is_test);
      v_n := 1;
    end if;
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  -- S8 (Ahmed, 26 Nov 2026): a social hand-off → the social team (their numbers of «التقارير»), never a reception slot; no
  -- WhatsApp escalation (the team was alerted at once; the waiting email follows)
  if h.social then
    if p_kind = 'alert' then
      v_n := internal.hub_social_alert(h.id, v_channel);
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  -- S2a: both branches (no longer created since S3; kept for a hand-off of before)
  if h.both_branches then
    v_n := internal.hub_both_alert(h.id, p_kind, false, p_now);
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  if p_kind = 'alert' then
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and internal.hub_slot_covers(s, p_now)
      on conflict do nothing;
      get diagnostics v_n = row_count;
      if v_n = 0 then
        insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
        select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
         where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
        on conflict do nothing;
        get diagnostics v_n = row_count;
      end if;
    end if;
    update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
  else
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'escalation', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
         and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
  end if;
  return v_n;
end;
$$;

create or replace function internal.hub_extra_alert(p_conversation uuid, p_reason text, p_summary text, p_ref text, p_managers boolean, p_reservation uuid)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  v_id uuid := gen_random_uuid();
  v_branch text;
  v_social boolean := false;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null then return null; end if;
  select * into u from public.hub_units where id = c.unit_id;
  if u.kind = 'brand' then
    -- S9 (Ahmed, 26 Nov 2026): a booking request on «السوشيال» goes to the reception of the branch the guest chose (the
    -- reservation's), like any chat booking request; S8: every other alert of «السوشيال» — and a booking request whose branch
    -- is somehow unknown — to the social team
    if p_reason in ('booking_request', 'booking_request_late', 'booking_request_again') then
      v_branch := coalesce((select r.branch from public.reservations r where r.id = p_reservation), c.branch_slug);
    end if;
    v_social := v_branch is null;
  else
    v_branch := u.branch_slug;
  end if;
  insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, summary, ref_text, is_test, extra, reservation_id, status, both_branches, social)
  values (v_id, c.id, c.unit_id, coalesce(v_branch, c.branch_slug, 'airport-road'), p_reason, left(p_summary, 120), left(p_ref, 40), c.is_test, true, p_reservation, 'pending',
          false, v_social);
  v_channel := internal.hub_branch_channel(coalesce(v_branch, c.branch_slug, 'airport-road'));
  if v_channel is not null and internal.hub_tester_conversation(c.id) then
    -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin
    if internal.hub_system_admin_recipient() is not null then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', v_id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', c.is_test);
      v_n := 1;
    end if;
  elsif v_social then
    v_n := internal.hub_social_alert(v_id, v_channel);
  elsif v_channel is not null then
    if not coalesce(p_managers, false) then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and internal.hub_slot_covers(s, now())
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    if v_n = 0 then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and s.role = 'manager'
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
  end if;
  update public.hub_handoffs set alerted_at = now(), status = case when v_n > 0 then 'alerted' else 'email_only' end where id = v_id;
  return v_id;
end;
$$;

create or replace function public.hub_comment_done(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
  v_state text := p ->> 'state';
  v_handoff uuid;
  m jsonb;
  v_question boolean := (p ->> 'handoff_reason') = 'comment_question';
begin
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  if v_state not in ('replied', 'handed_off', 'skipped', 'review', 'test', 'failed') then raise exception 'hub_comment_state' using errcode = '22023'; end if;
  update public.hub_comments set
    class = coalesce(p ->> 'class', class), language = coalesce(p ->> 'language', language), state = v_state,
    skip_reason = nullif(p ->> 'reason', ''), classified_at = coalesce(classified_at, case when p ? 'class' then now() end), done_at = now(),
    public_body = coalesce(left(p ->> 'public_body', 1000), public_body), public_variant = coalesce((p ->> 'public_variant')::integer, public_variant),
    public_id = coalesce(nullif(p ->> 'public_id', ''), public_id), public_status = coalesce(nullif(p ->> 'public_status', ''), public_status),
    public_error = coalesce(nullif(p ->> 'public_error', ''), public_error), public_at = case when p ? 'public_status' then now() else public_at end,
    private_body = coalesce(left(p ->> 'private_body', 1000), private_body), private_status = coalesce(nullif(p ->> 'private_status', ''), private_status),
    private_error = coalesce(nullif(p ->> 'private_error', ''), private_error), private_at = case when p ? 'private_status' then now() else private_at end,
    conversation_id = coalesce(nullif(p ->> 'conversation_id', '')::uuid, conversation_id),
    post_permalink = coalesce(nullif(p ->> 'post_permalink', ''), post_permalink), post_thumb = coalesce(nullif(p ->> 'post_thumb', ''), post_thumb),
    post_product = coalesce(nullif(p ->> 'post_product', ''), post_product)
   where id = c.id;
  -- the classifier's cost, on «السوشيال» (layer tag)
  if (p ->> 'input_tokens') is not null then
    perform internal.hub_usage_add(ch.unit_id, 'tag', 'turn', coalesce(p ->> 'model', 'claude-sonnet-5-5'), (p ->> 'input_tokens')::bigint, coalesce((p ->> 'output_tokens')::bigint, 0), c.is_test);
  end if;
  -- S2e: the private answer's model calls (the engine on «السوشيال»)
  for m in select * from jsonb_array_elements(case when jsonb_typeof(p -> 'models') = 'array' then p -> 'models' else '[]'::jsonb end) loop
    if coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      perform internal.hub_usage_add(ch.unit_id, case when m ->> 'layer' in ('understand', 'compose', 'tag', 'vision', 'summary') then m ->> 'layer' else 'understand' end, 'turn',
                                     coalesce(m ->> 'model', 'claude-sonnet-5-5'), coalesce((m ->> 'input_tokens')::bigint, 0), coalesce((m ->> 'output_tokens')::bigint, 0), c.is_test);
    end if;
  end loop;
  -- a complaint: the comment's hand-off — both branches (a test account's: the system admin only, S1c)
  -- S8 (Ahmed, 26 Nov 2026): a comment for review («تعليقات تحتاج مراجعة») is a hand-off of the comment too — the social team
  if v_state in ('handed_off', 'review') and c.handoff_id is null then
    v_handoff := gen_random_uuid();
    insert into public.hub_handoffs (id, conversation_id, comment_id, unit_id, branch_slug, reason, summary, ref_text, is_test, both_branches, social)
    values (v_handoff, null, c.id, ch.unit_id, 'airport-road', case when v_state = 'review' then 'comment_review' when v_question then 'comment_question' else 'comment_complaint' end,
            case when v_state = 'review' then (case when c.kind = 'instagram' then 'تعليق على انستجرام يحتاج مراجعة' else 'تعليق على فيسبوك يحتاج مراجعة' end)
                 when v_question then (case when c.kind = 'instagram' then 'سؤال في تعليق على انستجرام يحتاج الفريق' else 'سؤال في تعليق على فيسبوك يحتاج الفريق' end)
                 when c.kind = 'instagram' then 'شكوى في تعليق على انستجرام' else 'شكوى في تعليق على فيسبوك' end, 'تعليق', c.is_test, false, true);
    update public.hub_comments set handoff_id = v_handoff where id = c.id;
    perform internal.hub_handoff_queue(v_handoff, 'alert');
  end if;
  return jsonb_build_object('ok', true, 'handoff_id', v_handoff);
end;
$$;

create or replace function public.hub_escalations_claim(p_now timestamptz default now(), p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_esc integer := internal.hub_setting_int('hub_escalate_min', 30);
  r record;
  v_to text[];
  v_out jsonb := '[]'::jsonb;
begin
  for r in select c.id, c.state, c.waiting_since, u.branch_slug, u.kind as unit_kind, c.branch_slug as conv_branch, coalesce(v.name_ar, u.name_ar) as unit_name
             from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.dining_venues v on v.id = u.dining_venue_id
            where c.state = 'human' and c.waiting_since is not null and c.escalated_at is null and not c.is_test
              and c.waiting_since <= p_now - make_interval(mins => v_esc)
            order by c.waiting_since limit least(greatest(coalesce(p_limit, 20), 1), 100)
            for update of c skip locked loop
    update public.hub_conversations set escalated_at = p_now where id = r.id;
    select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x
     where x.scope = 'branch' and x.active and x.branch_slug = r.branch_slug;
    -- S1c (Ahmed, 25 Nov 2026): a test account's conversation emails only the active admins
    if internal.hub_tester_conversation(r.id) then
      v_to := array(select u.email from public.staff s join auth.users u on u.id = s.user_id where s.active and s.role = 'admin' and u.email is not null order by u.email);
    -- S8 (Ahmed, 26 Nov 2026): «السوشيال» → the social team, never a branch or central recipient
    elsif r.unit_kind = 'brand' then
      v_to := internal.hub_social_team_emails();
    elsif cardinality(v_to) = 0 then
      select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'central' and x.active;
    end if;
    v_out := v_out || jsonb_build_object('id', r.id, 'short', upper(left(replace(r.id::text, '-', ''), 8)), 'unit_name', r.unit_name, 'state', r.state,
                                         'waiting_min', floor(extract(epoch from p_now - r.waiting_since) / 60)::integer, 'recipients', to_jsonb(v_to));
  end loop;
  return v_out;
end;
$$;

create or replace function public.hub_complaint_claim(p_conversation uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  v_to text[];
  v_id uuid;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or c.is_test then return jsonb_build_object('ok', false, 'reason', 'test'); end if;
  select * into u from public.hub_units where id = c.unit_id;
  insert into public.hub_alerts (kind, unit_id, payload) values ('complaint', u.id, jsonb_build_object('item', c.id::text))
  on conflict do nothing returning id into v_id;
  if v_id is null then return jsonb_build_object('ok', false, 'reason', 'already'); end if;
  select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'branch' and x.branch_slug = u.branch_slug and x.active;
  -- S8 (Ahmed, 26 Nov 2026): a complaint on «السوشيال» → the social team's addresses (a test account's → the admins, S1c)
  if u.kind = 'brand' then
    v_to := case when internal.hub_tester_conversation(c.id)
                 then array(select au.email from public.staff s join auth.users au on au.id = s.user_id where s.active and s.role = 'admin' and au.email is not null order by au.email)
                 else internal.hub_social_team_emails() end;
  elsif cardinality(v_to) = 0 then
    select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'central' and x.active;
  end if;
  update public.hub_alerts set sent_at = now(), sent_to = v_to where id = v_id;
  return jsonb_build_object('ok', true, 'id', c.id, 'short', upper(left(replace(c.id::text, '-', ''), 8)),
                            'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar), 'recipients', to_jsonb(v_to));
end;
$$;

create or replace function public.hub_staff_sends_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s record;
  v_out jsonb := '[]'::jsonb;
begin
  for s in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, coalesce(sl.phone, rr.phone) as to_phone,
                  coalesce(sl.active, rr.active, false) as target_active, h.token, h.branch_slug, h.summary, h.ref_text, h.reason, h.conversation_id,
                  h.closed_at, h.first_reply_at, h.both_branches, h.comment_id, h.social
             from public.hub_staff_sends x
             left join public.hub_channels ch on ch.id = x.channel_id
             left join public.hub_staff_slots sl on sl.id = x.slot_id
             left join public.hub_report_recipients rr on rr.id = x.recipient_id
             left join public.hub_handoffs h on h.id = x.handoff_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false) order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of x skip locked loop
    -- an alert or escalation whose hand-off was answered or closed meanwhile is not sent
    if s.to_phone is null or not s.target_active or s.from_address is null
       or (s.kind in ('alert', 'escalation') and (s.closed_at is not null or s.first_reply_at is not null)) then
      update public.hub_staff_sends set status = 'skipped', error_code = case when s.from_address is null then 'no_channel' when s.to_phone is null or not s.target_active then 'no_recipient' else 'answered' end, updated_at = now()
       where id = s.id;
      continue;
    end if;
    update public.hub_staff_sends set status = 'pending', updated_at = now() where id = s.id;
    v_out := v_out || jsonb_build_object(
      'id', s.id, 'kind', s.kind, 'template', s.template, 'language', 'ar', 'is_test', s.is_test,
      'channel_id', s.channel_id, 'from', s.from_address, 'waba_id', s.waba_id, 'sending_enabled', s.sending_enabled, 'to', s.to_phone,
      'handoff', case when s.handoff_id is not null then coalesce((
        select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'both', coalesce(s.both_branches, false), 'social', coalesce(s.social, false), 'summary', s.summary, 'ref', s.ref_text, 'reason', s.reason,
                 'guest_name', coalesce((select nullif(btrim(r.guest_name), '') from public.reservations r where r.phone = g.phone and not r.is_test order by r.created_at desc limit 1),
                                        nullif(btrim(g.wa_profile_name), '')),
                 'guest_phone', g.phone,
                 -- S1c: a social guest has no phone — the alert names the channel instead
                 'channel_kind', (select ch.kind from public.hub_channels ch where ch.id = c.channel_id),
                 -- S3: a social hand-off names the conversation's branch when the guest gave one
                 'social_branch', c.branch_slug)
          from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id where c.id = s.conversation_id),
        -- S2: a complaint in a comment — the commenter's name, the channel «تعليق انستجرام» / «تعليق فيسبوك», no phone
        (select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'both', coalesce(s.both_branches, false), 'social', coalesce(s.social, false), 'summary', s.summary, 'ref', s.ref_text,
                  'reason', s.reason, 'guest_name', cm.author_name, 'guest_phone', null, 'channel_kind', cm.kind || '_comment')
           from public.hub_comments cm where cm.id = s.comment_id)) end,
      'report', case when s.kind = 'report' then (select jsonb_build_object('day', d.day, 'data', d.data) from public.hub_daily_reports d where d.day = s.report_day)
                     when s.kind = 'report_test' then jsonb_build_object('day', s.report_day, 'data', s.payload) end);
  end loop;
  return v_out;
end;
$$;

-- the alert's link: the conversation or the comment for who may see it; a booking request's alert opens the booking for
-- the chosen branch's reception (S9 — they never see the social conversation)
create or replace function public.hub_alert_open(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_ref text;
  v_branch text;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{32}$' then return jsonb_build_object('allowed', false, 'reason', 'invalid'); end if;
  select * into h from public.hub_handoffs where token = p_token;
  if h.id is null then return jsonb_build_object('allowed', false, 'reason', 'not_found'); end if;
  if not (internal.can_conv_id(h.conversation_id, 'view') or (h.comment_id is not null and internal.hub_can_comments('view'))) then
    if h.extra and h.reservation_id is not null then
      select r.ref, r.branch into v_ref, v_branch from public.reservations r where r.id = h.reservation_id;
      if v_ref is not null and internal.can('bookings', 'view') and internal.can_branch(v_branch) then
        if h.opened_at is null then
          update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'link' where id = h.id;
        end if;
        return jsonb_build_object('allowed', true, 'booking_ref', v_ref);
      end if;
    end if;
    return jsonb_build_object('allowed', false, 'reason', 'forbidden');
  end if;
  if h.opened_at is null then
    update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'link' where id = h.id;
  end if;
  return jsonb_build_object('allowed', true, 'conversation_id', h.conversation_id, 'comment_id', h.comment_id);
end;
$$;

create or replace function internal.hub_standby_reason(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when p_kind <> 'reply' then 'tag'
    when exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id')) then 'tap'
    -- S2e: the conversation's channel's own audience, else the unit's
    when u.kind = 'brand' and coalesce(internal.hub_channel_audience(c.channel_id), u.social_mode) <> 'standby' then 'off'
    when u.kind <> 'brand' and (not coalesce(t.standby_on, false) or coalesce(t.standby_minutes, 0) not between 1 and 30) then 'off'
    when internal.hub_assistant_engaged(p_conversation) and internal.hub_exchange_open(p_conversation, p_message, p_at) then 'engaged'
    -- S8 (Ahmed, 26 Nov 2026): «السوشيال» waits for the social team (no shifts) — «no_shift» only while the team is empty
    when u.kind = 'brand' and not internal.hub_social_team_ready() then 'no_shift'
    when u.kind <> 'brand' and not exists (select 1 from public.hub_staff_slots s where s.active and internal.hub_slot_covers(s, p_at) and s.branch_slug = u.branch_slug) then 'no_shift'
    else 'waiting' end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation
$$;

-- ── 5. the lab: s3-01 … s3-04 (S8: the social hand-off lines name «فريقنا», never reception; S9: the booking request's footer) ──
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($s3$[{"key":"s3-01","unit":"social","language":"ar","messages":["أبغى أعدّل حجزي وأغيّر تاريخ الوصول"],"context":{},"expect":{"action":"conversation","steps":[{"outcome":"handoff","must_not_include":["الاستقبال"]}]},"note":"S8 (Ahmed, 26 Nov 2026): a change to a booking on Instagram goes to the social team — the line names «فريقنا», never reception","tags":["conversation","social","s3","handoff"]},{"key":"s3-02","unit":"social","language":"ar","messages":["أبغى أحجز 3 غرف في طريق المطار من 10 ديسمبر إلى 12 ديسمبر"],"context":{},"expect":{"action":"conversation","steps":[{"outcome":"handoff","must_not_include":["الاستقبال"]}]},"note":"S8: 2–4 rooms on Messenger are arranged by the social team — never «فريق الاستقبال»","tags":["conversation","social","s3","handoff"]},{"key":"s3-03","unit":"social","language":"ar","messages":["أبغى أحجز في طريق الشفا من 10 ديسمبر إلى 12 ديسمبر لشخصين","بدون إفطار","[tap:book:1]","سالم أحمد","0551234567"],"context":{},"expect":{"action":"conversation","steps":[{"outcome":"ask"},{"outcome":"quote"},{"outcome":"ask"},{"outcome":"ask","must_include":["رقم جوالك"]},{"outcome":"summary","must_include":["واتساب"],"must_not_include":["هنا في أقرب"]}]},"note":"S9 (Ahmed, 26 Nov 2026): a booking request on Instagram goes to the chosen branch's reception; the summary says the confirmation reaches the guest on WhatsApp, never «here»","tags":["conversation","social","s3","booking"]},{"key":"s3-04","unit":"social","language":"en","messages":["I need to cancel my booking please"],"context":{},"expect":{"action":"conversation","steps":[{"outcome":"handoff","must_not_include":["reception"]}]},"note":"S8 in English: a cancellation on Instagram goes to the social team — never «reception»","tags":["conversation","social","s3","handoff"]}]$s3$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
